487:   ui.mapHeading.textContent = directions[index];
488: }
489: 
490: function updateHUD() {
491:   const liveHealth = Math.max(0, player.health);
492:   const engineP = Math.max(0, player.engine);
493:   const boostP = Math.max(0, player.boost);
494:   ui.healthBar.style.width = `${liveHealth}%`;
495:   ui.healthValue.textContent = `${Math.round(liveHealth)}`;
496:   ui.engineBar.style.width = `${engineP}%`;
497:   ui.engineValue.textContent = `${Math.round(engineP)}%`;
498:   ui.boostBar.style.width = `${boostP}%`;
499:   ui.boostValue.textContent = `${Math.round(boostP)}%`;
500:   ui.chargeValue.textContent = `${Math.round(player.charge)}%`;
501:   ui.speedValue.textContent = `${Math.round(Math.abs(player.speed) * 10)}`.padStart(3, '0');
502:   ui.missionCount.textContent = `${state.kills} / ${state.missionTarget}`;
503:   ui.missionProgress.style.width = `${(state.kills / state.missionTarget) * 100}%`;
504:   if (state.kills >= state.missionTarget) {
505:     ui.missionProgress.style.width = '100%';
506:   }
507:   ui.vehicleState.textContent = player.mode === 'car' ? 'READY' : 'ON FOOT';
508:   updateCompass();
509: }
510: 
511: function doDamage(amount) {
512:   player.health = Math.max(0, player.health - amount);
513:   state.flashTimer = 0.15;
514:   ui.damageFlash.style.opacity = '1';
515:   if (player.health <= 0) {
516:     player.health = 100;
517:     player.engine = 100;
518:     player.boost = 100;
519:     player.charge = 82;
520:     if (player.mode === 'car') {
521:       playerCar.position.set(0, 0, 2);
522:       playerCar.rotation.y = 0;
523:     } else {
524:       agent.position.set(0, 0, 2);
525:     }
526:     showToast('PATROL RESET', 'Systems restored.');
527:   }
528: }
529: 
530: function activatePulse(origin, dir) {
531:   const trail = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 12, 8), mats.pulse);
532:   trail.position.copy(origin.clone().add(dir.clone().multiplyScalar(5.5)));
533:   trail.lookAt(origin.clone().add(dir.clone().multiplyScalar(14)));
534:   trail.scale.y = 1;
535:   scene.add(trail);
536:   setTimeout(() => scene.remove(trail), 120);
537: }
538: 
539: function firePulse() {
540:   if (state.paused || player.fireCooldown > 0) return;
541:   player.fireCooldown = 0.22;
542:   const origin = player.mode === 'car' ? playerCar.position.clone().add(new THREE.Vector3(0, 1.2, -3.1)) : agent.position.clone().add(new THREE.Vector3(0, 1.5, 0));
543:   const dir = new THREE.Vector3(Math.sin(player.heading), 0, -Math.cos(player.heading));
544:   if (player.mode === 'foot') {
545:     dir.set(Math.sin(player.heading), 0, -Math.cos(player.heading));
546:   }
547:   activatePulse(origin, dir);
548: 
549:   let damageDealt = false;
550:   for (const threat of enemyCars) {
551:     if (!threat.alive) continue;
552:     const toTarget = threat.mesh.position.clone().sub(origin);
553:     const dist = toTarget.length();
554:     const forward = dir.clone();
555:     const angle = forward.angleTo(toTarget.clone().normalize());
556:     if (dist < 24 && angle < 0.65) {
557:       threat.hp -= 34;
558:       damageDealt = true;
559:       if (threat.hp <= 0) {
560:         threat.alive = false;
561:         threat.mesh.visible = false;
562:         state.kills += 1;
563:         showToast(threat.boss ? 'MARINER DOWN' : 'THREAT ELIMINATED', threat.boss ? 'Bayfront secured.' : 'Hostile neutralized.');
564:         if (state.kills >= state.missionTarget) {
565:           showToast('AREA SECURED', 'The waterfront is clear.');
566:           ui.bossBanner.style.opacity = '0';
567:           setTimeout(() => showGlobalToast('Mission complete — district safe.'), 500);
568:         }
569:       }
570:     }
571:   }
572:   if (!damageDealt) {
573:     showGlobalToast('Pulse discharged');
574:   }
575: }
576: 
577: function clampToMap(value, size = 150) {
578:   return Math.min(size - 3, Math.max(-size + 3, value));
579: }
580: 
581: function setActivePlayerPositionFollow() {
582:   const targetPos = player.mode === 'car' ? playerCar.position.clone() : agent.position.clone();
583:   const offset = new THREE.Vector3(Math.sin(player.heading) * 10, 7.5, -Math.cos(player.heading) * 10);
584:   const desired = targetPos.clone().add(offset);
585:   camera.position.lerp(desired, 0.08);
586:   const focus = targetPos.clone().add(new THREE.Vector3(0, 1.5, 0));
587:   camera.lookAt(focus);
588: }
589: 
590: const keysDown = {
591:   accelerate: () => !!(keys.w || keys.arrowup),
592:   brake: () => !!(keys.s || keys.arrowdown),
593:   left: () => !!(keys.a || keys.arrowleft),
594:   right: () => !!(keys.d || keys.arrowright),
595:   boost: () => !!(keys.shift),
596: };
597: 
598: function updatePlayer(dt) {
599:   const carMode = player.mode === 'car';
600:   const steer = (keysDown.right() ? 1 : 0) - (keysDown.left() ? 1 : 0);
601: 
602:   if (carMode) {
603:     const throttle = (keysDown.accelerate() ? 1 : 0) - (keysDown.brake() ? 1 : 0);
604:     if (Math.abs(steer) > 0) {
605:       player.heading += steer * 1.8 * dt;
606:     }
607:     const forward = new THREE.Vector3(Math.sin(player.heading), 0, -Math.cos(player.heading));
608:     const accelerating = throttle !== 0;
609:     if (accelerating) {
610:       const accel = throttle > 0 ? 24 : 18;
611:       player.speed += accel * throttle * dt;
612:       player.engine = Math.max(0, player.engine - 1.2 * dt);
613:     } else {
614:       player.speed *= 0.97;
615:       player.engine = Math.min(100, player.engine + 0.7 * dt);
616:     }
617:     if (keysDown.boost() && player.boost > 0) {
618:       player.speed += 18 * dt;
619:       player.boost = Math.max(0, player.boost - 32 * dt);
620:       player.charge = Math.max(0, player.charge - 0.8 * dt);
621:     } else {
622:       player.boost = Math.min(100, player.boost + 12 * dt);
623:     }
624:     player.speed = THREE.MathUtils.clamp(player.speed, -14, 42);
625:     playerCar.position.addScaledVector(forward, player.speed * dt);
626:     playerCar.position.x = clampToMap(playerCar.position.x);
627:     playerCar.position.z = clampToMap(playerCar.position.z);
628:     playerCar.rotation.y = player.heading;
629:     playerCar.visible = true;
630:     agent.visible = false;
631:     player.x = playerCar.position.x;
632:     player.z = playerCar.position.z;
633:   } else {
634:     const movement = new THREE.Vector3((keysDown.right() ? 1 : 0) - (keysDown.left() ? 1 : 0), 0, (keysDown.accelerate() ? 1 : 0) - (keysDown.brake() ? 1 : 0));
635:     const stepSpeed = 16;
636:     if (movement.lengthSq() > 0.01) {
637:       movement.normalize();
638:       const headingTarget = Math.atan2(movement.x, -movement.z);
639:       player.heading = THREE.MathUtils.lerp(player.heading, headingTarget, 0.18);
640:       const moveVec = new THREE.Vector3(movement.x * stepSpeed * dt, 0, movement.z * stepSpeed * dt);
641:       agent.position.add(moveVec);
642:       agent.position.x = clampToMap(agent.position.x);
643:       agent.position.z = clampToMap(agent.position.z);
644:       agent.rotation.y = player.heading + Math.PI;
645:     }
646:     agent.visible = true;
647:     playerCar.visible = false;
648:     player.x = agent.position.x;
649:     player.z = agent.position.z;
650:     playerCar.position.x = player.x;
651:     playerCar.position.z = player.z;
652:   }
653: 
654:   const target = player.mode === 'car' ? playerCar.position : agent.position;
655:   target.y = 0;
656: 
657:   if (player.fireCooldown > 0) player.fireCooldown -= dt;
658:   player.charge = Math.min(100, player.charge + 0.15 * dt);
659:   player.engine = Math.max(0, player.engine - (player.mode === 'car' && Math.abs(player.speed) > 5 ? 0.18 : 0) * dt * 60);
660: }
661: 
662: function updateThreats(dt) {
663:   for (const threat of enemyCars) {
664:     if (!threat.alive) continue;
665:     const target = player.mode === 'car' ? playerCar.position : agent.position;
666:     const offset = target.clone().sub(threat.mesh.position);
667:     const dist = offset.length();
668:     const dir = offset.clone().normalize();
669:     if (dist > 0.001) {
670:       const move = dir.multiplyScalar(threat.speed * dt);
671:       threat.mesh.position.add(move);
672:       threat.mesh.position.x = clampToMap(threat.mesh.position.x);
673:       threat.mesh.position.z = clampToMap(threat.mesh.position.z);
674:       threat.mesh.rotation.y = Math.atan2(dir.x, -dir.z);
675:       if (dist < 9) {
676:         threat.attackCooldown -= dt;
677:         if (threat.attackCooldown <= 0) {
678:           threat.attackCooldown = 0.8;
679:           doDamage(threat.boss ? 12 : 8);
680:         }
681:       }
682:     }
683:     threat.mesh.userData.glow.material.opacity = 0.35 + Math.sin(performance.now() * 0.01 + threat.mesh.position.x) * 0.2;
684:   }
685: }
686: 
687: function drawMinimap() {
688:   const ctx = ui.mapCanvas.getContext('2d');
689:   const w = ui.mapCanvas.width, h = ui.mapCanvas.height;
690:   ctx.clearRect(0, 0, w, h);
691:   ctx.fillStyle = 'rgba(10, 18, 22, 0.8)';
692:   ctx.fillRect(0, 0, w, h);
693:   ctx.strokeStyle = 'rgba(187, 214, 203, 0.35)';
694:   ctx.lineWidth = 1;
695:   for (let x = 0; x <= 4; x++) {
696:     ctx.beginPath();
697:     ctx.moveTo((w / 4) * x, 0); ctx.lineTo((w / 4) * x, h); ctx.stroke();
698:   }
699:   for (let y = 0; y <= 4; y++) {
700:     ctx.beginPath();
701:     ctx.moveTo(0, (h / 4) * y); ctx.lineTo(w, (h / 4) * y); ctx.stroke();
702:   }
703:   ctx.fillStyle = '#7ba6b0';
704:   ctx.fillRect(w * 0.28, h * 0.28, w * 0.44, h * 0.44);
705:   ctx.fillStyle = '#2d3d32';
706:   ctx.fillRect(w * 0.22, h * 0.22, w * 0.56, h * 0.56);
707: 
708:   const xToMap = (x) => ((x + 160) / 320) * w;
709:   const zToMap = (z) => ((z + 160) / 320) * h;
710: 
711:   ctx.strokeStyle = 'rgba(220, 212, 176, 0.7)';
712:   for (let roadX = -120; roadX <= 120; roadX += 48) {
713:     const fx = xToMap(roadX);
714:     ctx.beginPath(); ctx.moveTo(fx, 0); ctx.lineTo(fx, h); ctx.stroke();
715:   }
716:   for (let roadZ = -120; roadZ <= 120; roadZ += 48) {
717:     const fz = zToMap(roadZ);
718:     ctx.beginPath(); ctx.moveTo(0, fz); ctx.lineTo(w, fz); ctx.stroke();
719:   }
720: 
721:   for (const threat of enemyCars) {
722:     if (!threat.alive) continue;
723:     const px = xToMap(threat.mesh.position.x), py = zToMap(threat.mesh.position.z);
724:     ctx.fillStyle = threat.boss ? '#ff8e6f' : '#ff5d5d';
725:     ctx.beginPath();
726:     ctx.arc(px, py, threat.boss ? 5 : 4, 0, Math.PI * 2);
727:     ctx.fill();
728:   }
729: 
730:   const px = xToMap(playerCar.position.x || agent.position.x), py = zToMap(playerCar.position.z || agent.position.z);
731:   ctx.save();
732:   ctx.translate(px, py);
733:   ctx.rotate(-player.heading);
734:   ctx.fillStyle = '#a9e7c3';
735:   ctx.beginPath();
736:   ctx.moveTo(0, -7); ctx.lineTo(5, 7); ctx.lineTo(0, 5); ctx.lineTo(-5, 7); ctx.closePath();
737:   ctx.fill();
738:   ctx.restore();
739: }
740: 
741: function updateClock() {
742:   const now = new Date();
743:   const h = now.getHours().toString().padStart(2, '0');
744:   const m = now.getMinutes().toString().padStart(2, '0');
745:   ui.clockText.textContent = `${h}:${m}`;
746: }
747: 
748: const clock = new THREE.Clock();
749: 
750: function animate() {
751:   const dt = Math.min(clock.getDelta(), 0.033);
752:   requestAnimationFrame(animate);
753: 
754:   if (!state.paused) {
755:     updatePlayer(dt);
756:     updateThreats(dt);
757:     setActivePlayerPositionFollow();
758:     if (player.mode === 'car') {
759:       playerCar.position.y = 0;
760:     } else {
761:       agent.position.y = 0;
762:     }
763:   }
764: 
765:   if (state.flashTimer > 0) {
766:     state.flashTimer -= dt;
767:     ui.damageFlash.style.opacity = String(Math.max(0, state.flashTimer / 0.15));
768:   }
769: 
770:   drawMinimap();
771:   updateHUD();
772:   updateClock();
773:   renderer.render(scene, camera);
774: }
775: 
776: ui.timeToggle.addEventListener('click', () => {
777:   state.day = !state.day;
778:   updateLighting();
779: });
780: ui.soundToggle.addEventListener('click', () => {
781:   state.audio = !state.audio;
782:   ui.soundToggle.style.opacity = state.audio ? '1' : '0.65';
783:   showToast(state.audio ? 'SOUND ON' : 'SOUND OFF', 'Audio output toggled.');
784: });
785: ui.pauseButton.addEventListener('click', () => setPaused(!state.paused));
786: ui.resumeButton.addEventListener('click', () => setPaused(false));
787: ui.dismissHelp.addEventListener('click', () => ui.helpPill.classList.add('hidden'));
788: ui.fireTouch.addEventListener('click', firePulse);
789: ui.driveTouch.addEventListener('click', () => setVehicleMode(true));
790: ui.enterTouch.addEventListener('click', () => toggleVehicleMode());
791: ui.boostTouch.addEventListener('click', () => {
792:   keys.shift = true;
793:   setTimeout(() => { keys.shift = false; }, 200);
794: });
795: 
796: window.addEventListener('resize', () => {
797:   camera.aspect = innerWidth / innerHeight;
798:   camera.updateProjectionMatrix();
799:   renderer.setSize(innerWidth, innerHeight);
800: });
801: 
802: function initialize() {
803:   setVehicleMode(true);
804:   updateLighting();
805:   updateHUD();
806:   setPaused(false);
807:   ui.loading.classList.add('hidden');
808:   setTimeout(() => {
809:     ui.loading.style.display = 'none';
810:   }, 650);
811:   showToast('MISSION LIVE', 'Clear the waterfront.');
812: }
813: 
814: setTimeout(initialize, 400);
815: animate();

